ValidationRule.errorConditionFormula:
OR(
        AND(
            ISCHANGED(Interview_Status__c),
            OR(
                ISBLANK(Feedback__c),
                Feedback__c = PRIORVALUE(Feedback__c)
            )
        ),
        AND(
            ISCHANGED(Round__c),
            OR(
                ISBLANK(Feedback__c),
                Feedback__c = PRIORVALUE(Feedback__c)
            )
        )
)
